<script>
$(function(){
 let step=1, photos=[], draftKey='raymondReportStudioDraftV1';
 const stepNames=['Student details','Placement details','Practical experience','Photographs','Final details'];
 function toast(msg){$('#toastText').text(msg);bootstrap.Toast.getOrCreateInstance(document.getElementById('toast'),{delay:3500}).show();}
 function val(id, fallback=''){return ($('#'+id).val()||'').trim()||fallback;}
 function esc(s){return $('<div>').text(s||'').html();}
 function paragraphs(text,fallback){let s=(text||'').trim();if(!s)return '<p>'+esc(fallback)+'</p>';return s.split(/\n+/).map(x=>'<p>'+esc(x.trim())+'</p>').join('');}
 function updateProgress(){ $('#stepNumber').text(step);$('#stepLabel').text(stepNames[step-1]);$('#progressText').text('Step '+step+' of 5');$('#progressBar').css('width',(step*20)+'%');$('.step-section').addClass('d-none');$('.step-section[data-step="'+step+'"]').removeClass('d-none');$('#prevBtn').prop('disabled',step===1);$('#nextBtn').html(step===5?'Build my report <i class="bi bi-check2 ms-1"></i>':'Continue <i class="bi bi-arrow-right ms-1"></i>'); }
 function updatePhotoGrid(){let html='';photos.forEach((p,i)=>{html+='<div class="col-6 col-md-4 photo-item"><img class="thumb" src="'+p.data+'" alt=""><button type="button" data-remove="'+i+'" aria-label="Remove photo">×</button><input class="form-control form-control-sm mt-1 photo-caption" data-caption="'+i+'" value="'+esc(p.caption||'')+'" placeholder="Photo caption"></div>';});$('#photoGrid').html(html);}
 function collect(){let o={};$('#reportForm').find('input,textarea').each(function(){if(this.type!=='file')o[this.id]=$(this).val();});o.photos=photos;return o;}
 function save(silent){try{localStorage.setItem(draftKey,JSON.stringify(collect()));$('#saveStatus').text('Saved on this device at '+new Date().toLocaleTimeString());if(!silent)toast('Your draft has been saved in this browser.');}catch(e){toast('Could not save. Try fewer or smaller photographs.');}}
 function restore(){try{let o=JSON.parse(localStorage.getItem(draftKey)||'null');if(!o)return;Object.keys(o).forEach(k=>{if(k==='photos')return;if($('#'+k).length)$('#'+k).val(o[k]);});photos=o.photos||[];updatePhotoGrid();}catch(e){}}
 function render(){
 let title=val('title','Field / Industrial Training Report'),student=val('student','Student Full Name'),uni=val('university','The University of Dodoma'),org=val('organisation','Host Organisation'),prog=[val('programme'),val('department'),val('college')].filter(Boolean).join(' • '),dates=[val('startDate'),val('endDate')].filter(Boolean).join(' to ')||'Training period not specified';
 $('#pTitle').text(title);$('#pStudent').text(student);$('#pReg').text(val('regno','Registration Number'));$('#pProgramme').text(prog||'Programme / Department');$('#pOrganisation').text(org);$('#pDates').text(dates);$('#pYear').text(val('year',new Date().getFullYear()));
 let content='';
 content+='<div class="report-page chapter"><h2>DECLARATION</h2>'+paragraphs('I, '+student+', declare that this field / industrial training report is based on the learning activities and experience I undertook during my placement at '+org+'. The work presented here is my own account, except where sources are acknowledged.','I declare that this report is my own work and that all sources used have been acknowledged.')+'<p class="mt-5">Student signature: ____________________________ &nbsp; Date: ______________</p><h2>CERTIFICATION</h2><p>This report has been prepared by '+esc(student)+'. It is submitted for academic consideration subject to review and approval by the relevant university and host-organisation supervisors.</p><p class="mt-5">University supervisor: _________________________ &nbsp; Date: ______________</p><p>Host supervisor: ______________________________ &nbsp; Date: ______________</p><h2>DEDICATION</h2>'+paragraphs(val('dedication'),'This report is dedicated to the people whose encouragement and support made this training experience possible.')+'</div>';
 content+='<div class="report-page chapter"><h2>ACKNOWLEDGEMENTS</h2>'+paragraphs(val('acknowledgements'),'I am grateful to the management and staff of '+org+' for welcoming me, sharing their knowledge and giving me an opportunity to learn through practical work. I also appreciate the guidance of my university and workplace supervisors, as well as the support of everyone who contributed to this training experience.')+'<h2>ABSTRACT</h2><p>This report presents the field / industrial training experience undertaken by '+esc(student)+' at '+esc(org)+(dates?' during '+esc(dates):'')+'. It outlines the purpose of the placement, the working environment, practical activities performed, tools and equipment used, challenges encountered and the knowledge and skills gained. The report also reflects on how the training connected classroom learning with real workplace responsibilities. The account is based on the information and experiences recorded by the student and should be reviewed for accuracy before submission.</p></div>';
 content+='<div class="report-page chapter"><h2>TABLE OF CONTENTS</h2>'+['Declaration','Certification','Dedication','Acknowledgements','Abstract','CHAPTER ONE: INTRODUCTION','CHAPTER TWO: ORGANISATION PROFILE','CHAPTER THREE: TRAINING ACTIVITIES AND PRACTICAL EXPERIENCE','CHAPTER FOUR: SKILLS, CHALLENGES AND LESSONS','CHAPTER FIVE: CONCLUSION AND RECOMMENDATIONS','References','Appendices'].map((x,i)=>'<div class="toc-row"><span>'+esc(x)+'</span><span>'+(i+1)+'</span></div>').join('')+'<p class="small mt-4">Update page numbers after final formatting if your department requires an automatically numbered contents page.</p></div>';
 content+='<div class="report-page chapter"><h2>CHAPTER ONE: INTRODUCTION</h2><h3>1.1 Background of the training</h3><p>Field / industrial training gives students an opportunity to experience a real working environment and understand how professional knowledge is applied in daily tasks. The placement at '+esc(org)+' provided an opportunity to observe workplace procedures, take part in assigned activities and develop a better understanding of the responsibilities associated with '+esc(title)+'.</p><h3>1.2 Objectives of the training</h3>'+paragraphs(val('objectives'),'The training aimed to connect academic knowledge with practical work, develop relevant technical and professional skills, understand workplace procedures and build confidence in carrying out tasks under supervision.')+'<h3>1.3 Scope of the report</h3><p>This report focuses on the organisation and working environment, the activities performed during the placement, tools and equipment used, practical lessons, challenges and recommendations. It describes the experience reported by the student rather than assuming activities that were not carried out.</p><h3>1.4 Organisation and duration</h3><p>The training was undertaken at '+esc(org)+', located in '+esc(val('location','the stated location'))+'. The recorded training period was '+esc(dates)+'.</p></div>';
 content+='<div class="report-page chapter"><h2>CHAPTER TWO: ORGANISATION PROFILE</h2><h3>2.1 Introduction</h3><p>'+esc(org)+' was the host organisation for the student's field / industrial training. This section should be completed with verified information about the organisation, including its history, mission, vision, services, organisational structure and the department in which the student was placed.</p><h3>2.2 Location and area of operation</h3><p>The organisation is located at '+esc(val('location','the location provided by the student'))+'. Add a brief, factual description of its main operations and the people or customers it serves.</p><h3>2.3 Department / unit of placement</h3><p>The student was attached to the relevant department or unit where assigned duties were carried out under guidance. Explain the department's responsibilities and how it contributes to the organisation.</p><h3>2.4 Working environment</h3><p>Describe the working environment, reporting arrangements, safety expectations, tools and resources available to staff and trainees. Include only details that you observed or confirmed.</p></div>';
 content+='<div class="report-page chapter"><h2>CHAPTER THREE: TRAINING ACTIVITIES AND PRACTICAL EXPERIENCE</h2><h3>3.1 Overview of activities</h3>'+paragraphs(val('activities'),'Describe the tasks you completed during the placement. Explain what you were asked to do, the steps you followed, the equipment or software involved, the supervision received and the outcome of each task.')+'<h3>3.2 Tools, equipment and materials</h3>'+paragraphs(val('tools'),'List the tools, equipment, materials and software used during the placement. For each important item, explain its purpose and how it was used safely.')+'<h3>3.3 Practical procedures</h3><p>For each major activity, present the objective, materials or tools required, procedure followed, observations and outcome. Use clear sequential steps and include diagrams or photographs where they genuinely help explain the work.</p><h3>3.4 Evidence from the field</h3><p>The photographs below should show actual training activities or equipment. Captions identify what is visible and why it is relevant to the task.</p>'+ (photos.length?photos.map((p,i)=>'<figure><img src="'+p.data+'" alt="Training evidence"><figcaption>Figure '+(i+1)+': '+esc(p.caption||'Practical training photograph')+'</figcaption></figure>').join(''):'<p>No photographs have been added yet. Return to Step 4 to upload practical evidence if available.</p>')+'</div>';
 content+='<div class="report-page chapter"><h2>CHAPTER FOUR: SKILLS, CHALLENGES AND LESSONS</h2><h3>4.1 Skills and knowledge gained</h3>'+paragraphs(val('skills'),'Explain the technical, communication, teamwork, problem-solving, safety and time-management skills you developed. Connect each skill to a real task or situation from the placement.')+'<h3>4.2 Challenges encountered</h3>'+paragraphs(val('challenges'),'Describe the difficulties you experienced, why they occurred and the steps taken with appropriate guidance to address them.')+'<h3>4.3 Relationship between theory and practice</h3><p>Reflect on how concepts learned in class were applied in the workplace. Give specific examples and explain any differences between classroom exercises and real working conditions.</p><h3>4.4 Professional growth</h3><p>Discuss how the placement influenced your confidence, professional conduct, communication, teamwork and understanding of workplace expectations.</p></div>';
 content+='<div class="report-page chapter"><h2>CHAPTER FIVE: CONCLUSION AND RECOMMENDATIONS</h2><h3>5.1 Conclusion</h3><p>The field / industrial training placement at '+esc(org)+' provided an opportunity to gain practical exposure and reflect on the application of academic learning in a workplace setting. The final conclusion should summarise the most important activities, outcomes and lessons that are supported by the student's actual experience.</p><h3>5.2 Recommendations</h3>'+paragraphs(val('recommendations'),'The host organisation may continue providing structured guidance and opportunities for trainees to participate in supervised practical work. The university may strengthen preparation before placement and maintain communication with host organisations. Future students should keep daily records, observe safety procedures and ask for clarification whenever a task is unfamiliar.')+'<h3>5.3 Personal reflection</h3><p>Conclude with a short reflection on the experience, the areas in which you improved and the skills you intend to continue developing.</p><h2>REFERENCES</h2>'+paragraphs(val('references'),'Add only sources that you actually consulted, using the referencing style required by your department. Include author or organisation, year, title and publication details or access information where applicable.')+'<h2>APPENDICES</h2><p>Attach supporting materials such as approved logbook extracts, additional photographs, diagrams, work schedules, sample configurations or other evidence permitted by the host organisation.</p></div>';
 $('#reportPages').html(content);
 }
 $('#reportForm').on('input change', 'input,textarea', function(){render();save(true);});
 $('#nextBtn').on('click',function(){if(step===1 && !val('student')){toast('Please enter your full name first.');$('#student').trigger('focus');return;}if(step===2 && !val('organisation')){toast('Please enter the host organisation.');$('#organisation').trigger('focus');return;}if(step===3 && !val('activities')){toast('Please describe at least one training activity.');$('#activities').trigger('focus');return;}if(step<5){step++;updateProgress();}else{render();$('#preview')[0].scrollIntoView({behavior:'smooth'});toast('Your report preview has been prepared. Review it before exporting.');} });
 $('#prevBtn').on('click',function(){if(step>1){step--;updateProgress();}});
 $('#photos').on('change',function(e){let files=Array.from(e.target.files||[]);files.forEach(file=>{if(!file.type.startsWith('image/'))return;if(file.size>3*1024*1024){toast(file.name+' is larger than 3 MB. Please resize it first.');return;}let reader=new FileReader();reader.onload=function(ev){photos.push({data:ev.target.result,caption:file.name.replace(/\.[^.]+$/,'')});updatePhotoGrid();render();save(true);};reader.readAsDataURL(file);});$(this).val('');});
 $('#photoGrid').on('click','button[data-remove]',function(){photos.splice(Number($(this).data('remove')),1);updatePhotoGrid();render();save(true);});
 $('#photoGrid').on('input','.photo-caption',function(){let i=Number($(this).data('caption'));if(photos[i])photos[i].caption=$(this).val();render();save(true);});
 $('#saveBtn').on('click',()=>save(false));
 function safeFileName(){return (val('student','Student').replace(/[^a-z0-9]+/gi,'_')+'_Field_Training_Report').replace(/^_|_$/g,'');}
 $('#pdfBtn').on('click',async function(){render();if(typeof html2pdf==='undefined'){toast('PDF library did not load. Check your internet connection and try again.');return;}let btn=$(this),old=btn.html();btn.prop('disabled',true).html('<span class="spinner-border spinner-border-sm me-1"></span>Preparing PDF...');try{let clone=document.getElementById('reportOutput').cloneNode(true);clone.style.background='#fff';clone.querySelectorAll('.report-page').forEach(p=>{p.style.boxShadow='none';p.style.margin='0';p.style.maxWidth='none';p.style.width='100%';p.style.minHeight='0';p.style.pageBreakAfter='always';});await html2pdf().set({margin:[12,12,12,12],filename:safeFileName()+'.pdf',image:{type:'jpeg',quality:.96},html2canvas:{scale:1.7,useCORS:true,backgroundColor:'#ffffff',logging:false},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'},pagebreak:{mode:['css','legacy']}}).from(clone).save();toast('Your PDF has been downloaded.');}catch(e){console.error(e);toast('PDF export could not finish. Please use Print and choose Save as PDF.');}finally{btn.prop('disabled',false).html(old);}});
 $('#printBtn').on('click',function(){render();window.print();});
 $('#wordBtn').on('click',async function(){render();if(!window.docx){toast('Word export library did not load. Check your internet connection.');return;}let btn=$(this),old=btn.html();btn.prop('disabled',true).html('<span class="spinner-border spinner-border-sm me-1"></span>Preparing Word...');try{const {Document,Packer,Paragraph,TextRun,HeadingLevel,AlignmentType,PageBreak}=window.docx;let children=[];const addPara=(text,opts={})=>children.push(new Paragraph({children:[new TextRun({text:String(text||''),bold:!!opts.bold,size:opts.size||24})],alignment:opts.center?AlignmentType.CENTER:AlignmentType.JUSTIFIED,spacing:{after:180}}));addPara(val('university','THE UNIVERSITY OF DODOMA').toUpperCase(),{bold:true,center:true,size:30});addPara('FIELD / INDUSTRIAL TRAINING REPORT',{bold:true,center:true,size:28});addPara(val('title','Field / Industrial Training Report').toUpperCase(),{bold:true,center:true,size:28});addPara('PREPARED BY',{center:true,bold:true});addPara(val('student','Student Full Name'),{center:true,bold:true});addPara('Registration Number: '+val('regno','Not provided'),{center:true});addPara(val('programme','Programme')+' | '+val('organisation','Host Organisation'),{center:true});addPara('Training period: '+val('startDate','')+' to '+val('endDate',''),{center:true});children.push(new Paragraph({children:[new PageBreak()]}));const section=(h,body)=>{children.push(new Paragraph({text:h,heading:HeadingLevel.HEADING_1,spacing:{before:280,after:180},pageBreakBefore:true}));(body||'').split(/\n+/).filter(Boolean).forEach(line=>addPara(line));};section('DECLARATION','I, '+val('student','Student Name')+', declare that this report is based on my field training experience at '+val('organisation','the host organisation')+'. I have acknowledged sources used.');section('ACKNOWLEDGEMENTS',val('acknowledgements','I sincerely thank the staff and supervisors who supported my training.'));section('ABSTRACT','This report describes the field / industrial training undertaken by '+val('student')+' at '+val('organisation')+'. It presents the objectives, practical activities, tools, skills gained, challenges and recommendations.');section('CHAPTER ONE: INTRODUCTION',val('objectives','The training aimed to connect academic learning with practical workplace experience.')+'\nThe placement was undertaken at '+val('organisation')+' in '+val('location','the stated location')+'.');section('CHAPTER TWO: ORGANISATION PROFILE','Describe the verified history, services, structure and department of '+val('organisation')+'. Add factual information confirmed with the organisation.');section('CHAPTER THREE: TRAINING ACTIVITIES',val('activities','Describe the practical activities completed.')+'\nTools and equipment: '+val('tools','Add tools and equipment used.')+'\nPhotographs uploaded: '+photos.length+' (see the PDF or print version for embedded images).');section('CHAPTER FOUR: SKILLS AND CHALLENGES','Skills gained: '+val('skills','Describe skills gained.')+'\nChallenges: '+val('challenges','Describe challenges and how you addressed them.'));section('CHAPTER FIVE: CONCLUSION AND RECOMMENDATIONS','Recommendations: '+val('recommendations','Add recommendations.')+'\nConclusion: Summarise your main learning outcomes.');section('REFERENCES AND APPENDICES',val('references','Add the references you actually consulted.')+'\nAttach relevant supporting evidence as appendices.');let doc=new Document({sections:[{properties:{page:{size:{width:11906,height:16838},margin:{top:1134,right:1134,bottom:1134,left:1134}}},children}]});let blob=await Packer.toBlob(doc);let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=safeFileName()+'.docx';a.click();URL.revokeObjectURL(a.href);toast('Your editable Word document has been downloaded.');}catch(e){console.error(e);toast('Word export failed. Please try again or use PDF export.');}finally{btn.prop('disabled',false).html(old);}});
 restore();render();updateProgress();
});
</script>
</body></html>